    "  overflow: hidden;\n"
    "}\n"
    ".progress-fill { height: 100%; width: 0; background: var(--accent); transition: width .3s; }\n"
    "\n"
    "/* ---------- reboot screen ---------- */\n"
    ".reboot-screen { display: none; padding: 30px 16px; text-align: center; }\n"
    ".reboot-screen h2 {\n"
    "  margin: 0 0 8px;\n"
    "  font-size: 20px;\n"
    "  font-weight: 650;\n"
    "  letter-spacing: -.01em;\n"
    "  text-transform: none;\n"
    "  color: var(--ok);\n"
    "}\n"
    ".reboot-screen p { font-size: 13px; color: var(--muted); margin: 0 0 6px; }\n"
    ".reboot-screen .countdown { font-family: var(--mono); font-size: 26px; color: var(--ink); margin: 10px 0; }\n"
    "\n"
    "/* ---------- ACL / scan specifics ---------- */\n"
    ".acl-section { margin-bottom: 10px; }\n"
    ".stats { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 0 0 8px; font-family: var(--mono); font-size: 10px; color: var(--muted); }\n"
    ".stats .allowed { color: var(--ok); }\n"
    ".stats .denied { color: var(--danger); }\n"
    ".refresh-note { margin: 0 0 10px; font-size: 11.5px; color: var(--muted); }\n"
    ".signal-bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 14px; vertical-align: middle; }\n"
    ".signal-bars .bar { width: 3px; border-radius: 0; background: #deddd6; }\n"
    ".signal-bars .bar.active.signal-excellent { background: var(--ok); }\n"
    ".signal-bars .bar.active.signal-good { background: #4f8f6a; }\n"
    ".signal-bars .bar.active.signal-fair { background: var(--warn); }\n"
    ".signal-bars .bar.active.signal-weak { background: #b57a16; }\n"
    ".signal-bars .bar.active.signal-poor { background: var(--danger); }\n"
    ".scan-actions { display: flex; justify-content: flex-end; margin-top: 2px; }\n"
    "\n"
    "/* ---------- modal ---------- */\n"
    ".modal-overlay {\n"
    "  display: none;\n"
    "  position: fixed;\n"
    "  inset: 0;\n"
    "  z-index: 1000;\n"
    "  background: rgba(20, 20, 18, .42);\n"
    "  justify-content: center;\n"
    "  align-items: center;\n"
    "  padding: 20px;\n"
    "}\n"
    ".modal-overlay.show { display: flex; }\n"
    ".modal-box {\n"
    "  width: 100%;\n"
    "  max-width: 400px;\n"
    "  padding: 20px;\n"
    "  border: 1px solid var(--line-2);\n"
    "  border-top: 3px solid var(--danger);\n"
    "  border-radius: 3px;\n"
    "  background: var(--surface);\n"
    "  box-shadow: 0 18px 50px rgba(0, 0, 0, .18);\n"
    "}\n"
    ".modal-box h3 {\n"
    "  margin: 0 0 8px;\n"
    "  font-family: var(--sans);\n"
    "  font-size: 15px;\n"
    "  font-weight: 650;\n"
    "  letter-spacing: 0;\n"
    "  text-transform: none;\n"
    "  color: var(--ink);\n"
    "}\n"
    ".modal-box p { margin: 0 0 16px; font-size: 12.5px; color: var(--muted); }\n"
    ".modal-box button {\n"
    "  height: 34px;\n"
    "  padding: 0 16px;\n"
    "  border: 1px solid var(--ink);\n"
    "  border-radius: 3px;\n"
    "  background: var(--ink);\n"
    "  color: #fff;\n"
    "  font: 600 12px var(--sans);\n"
    "  cursor: pointer;\n"
    "}\n"
    "\n"
    "/* ---------- footer / home ---------- */\n"
    ".foot {\n"
    "  display: flex;\n"
    "  flex-wrap: wrap;\n"
    "  align-items: center;\n"
    "  gap: 6px 8px;\n"
    "  margin-top: 6px;\n"
    "  padding: 14px 0 0;\n"
    "  border-top: 1px solid var(--line);\n"
    "  font-size: 10.5px;\n"
    "  color: var(--muted);\n"
    "}\n"
    ".foot a { color: var(--ink-2); }\n"
    ".foot .sep { color: var(--line-2); }\n"
    ".home-row { display: flex; justify-content: flex-end; margin: 2px 0 0; }\n"
    ".btn-home { background: var(--surface); border-color: var(--line-2); color: var(--ink-2); height: 34px; }\n"
    ".btn-home:hover { background: var(--surface-2); border-color: #b3b2aa; color: var(--ink); }\n"
    "\n"
    "\n"
    "/* ---------- page-specific helpers ---------- */\n"
    ".mini-action {\n"
    "  display: inline-flex;\n"
    "  align-items: center;\n"
    "  height: 24px;\n"
    "  padding: 0 7px;\n"
    "  border: 1px solid var(--danger-line);\n"
    "  border-radius: 2px;\n"
    "  color: var(--danger);\n"
    "  font-size: 10.5px;\n"
    "  text-decoration: none;\n"
    "}\n"
    ".mini-action:hover { background: #fdf4f3; color: var(--danger); }\n"
    ".group-label {\n"
    "  width: auto !important;\n"
    "  padding: 18px 0 4px !important;\n"
    "  color: var(--muted);\n"
    "  font-size: 10px;\n"
    "  font-weight: 650;\n"
    "  letter-spacing: .12em;\n"
    "  text-transform: uppercase;\n"
    "}\n"
    ".form-table .ok-button { width: 100%; margin-top: 8px; }\n"
    ".form-table .file-btn { margin-bottom: 6px; }\n"
    ".form-table td > .hint-block { margin-top: 4px; }\n"
    ".form-table input[type='password'] { margin-bottom: 6px; }\n"
    ".form-table td:last-child > .ok-button { display: flex; }\n"
    ".danger-body form { margin: 0 0 10px; }\n"
    ".card-head .orange-button {\n"
    "  height: 26px;\n"
    "  padding: 0 9px;\n"
    "  font-size: 10.5px;\n"
    "}\n"
    ".empty {\n"
    "  padding: 18px 12px !important;\n"
    "  text-align: center;\n"
    "  color: var(--muted);\n"
    "  font-size: 12px;\n"
    "}\n"
    ".scanning { color: var(--accent); }\n"
    ".auth-form .hint { margin: 8px 0 0; }\n"
    "\n"
    "/* keep the topbar actions from squeezing the brand on small phones */\n"
    "@media (max-width: 380px) {\n"
    "  .brand-name { display: none; }\n"
    "  .logout { padding: 5px 7px; font-size: 11px; }\n"
    "}\n"
    "\n"
    "/* ---------- small screens ---------- */\n"
    "@media (max-width: 560px) {\n"
    "  .topbar-in { padding: 10px 16px; }\n"
    "  .brand-name { font-size: 12.5px; }\n"
    "  #container { padding: 0 16px 34px; }\n"
    "  .page-head { padding: 22px 0 14px; }\n"
    "  h1 { font-size: 23px; }\n"
    "  .card-head, .card > form, .card-body, .danger-body, .auth-form { padding-left: 14px; padding-right: 14px; }\n"
    "  .status-table td { padding: 8px 14px; }\n"
    "  .status-table td:first-child { width: 46%; font-size: 12px; }\n"
    "  .nav-grid { gap: 6px; margin-bottom: 14px; }\n"
    "  .nav-tile { padding: 10px; font-size: 12px; }\n"
    "\n"
    "  .form-table tr { display: block; }\n"
    "  .form-table td { display: block; width: auto; padding: 0; }\n"
    "  .form-table td:first-child { width: auto; padding: 10px 0 4px; }\n"
    "  .form-table td:empty { display: none; }\n"
    ".form-table td[colspan] {\n"
    "  width: auto;\n"
    "  text-transform: none;\n"
    "  letter-spacing: normal;\n"
    "  font-size: 12.5px;\n"
    "  font-weight: 400;\n"
    "  color: var(--ink-2);\n"
    "}\n"
    ".form-table td.group-label {\n"
    "  width: auto;\n"
    "  padding: 18px 0 4px;\n"
    "  color: var(--muted);\n"
    "  font-size: 10px;\n"
    "  font-weight: 650;\n"
    "  letter-spacing: .12em;\n"
    "  text-transform: uppercase;\n"
    "}\n"
    "  .form-table tr:first-child td:first-child { padding-top: 4px; }\n"
    "  .form-table input[type='number'] { width: 120px; }\n"
    "\n"
    "  .data-table th, .data-table td { padding: 8px 10px; }\n"
    "  .data-table { min-width: 0; }\n"
    "  .traffic-col, .col-idx, .col-sport, .col-dport, .col-hits { display: none; }\n"
    "  .data-table th, .data-table td { padding-left: 8px; padding-right: 8px; }\n"
    "  .table-scroll { margin: 0 -1px; }\n"
    "}\n"
    "\n"
    ;
static const size_t theme_css_len = sizeof(theme_css) - 1;

#endif /* THEME_CSS_H */
